StructuredTextModel.Text:
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//	NAME:			 HE_VFD_Logic                                                                                                                                                                                                                                                                    
//	CREATOR:		 Jan Magne Dybvik, Helgevold Elektro                                                                                                                                                                                                                                             
//                                                                                                                                                                                                                                                                                                                            
//------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ 
//  VERSION LOG:                                                                                                                                                                                                                                                                                                   
//	VERSION			DATE				SIGN							DESCRIPTION                                                                                                                                                                                                                                 
//	1.0.0					27.02.2025		JMD								Initial Release
//	1.0.1					15.04.2025		Ruben Byman				Bug fix Start Blocked state and state visible
//	1.0.2					29.04.2025		Ruben Byman				Added action on fault and predefined output and alarm trigger
//	1.0.3					06.05.2025		Ruben Byman				Changed Timer_StartTime from STRING to 2x INTs
//	1.0.4					10.06.2025		Fredrik Bjerkenes			Added NOT infront of inp_loto in line 68(Start blocked)  and 195 (In case of interlock)
// 1.0.5 				16.06.2025		Fredrik Bjerkenes 		Added Reset TOF to set reset fault TRUE for 500ms
// 1.0.6					15.08.2025		Fredrik Bjerkenes 		Ext.VFD.General.Running was not used. 
// 1.0.7					26.08.2025		William Veim				Removed duplicated writing to Active fault
// 1.0.8					28.08.2025		William Veim				Operator reset logic (newly added in structure)
// 1.0.9					02.09.2025		William Veim				Removed warning input as trigger for active alarm
// 1.0.10				17.09.2025		William Veim				Bugfix reset bit
// 1.0.11				16.10.2025		William Veim				Bugfix energy consuption
// 1.0.12				24.10.2025		William Veim				Logic for reverse running
// 1.0.13				11.11.2025		William Veim				Bugfix reverse running
// 1.0.14				13.12.2025		William Veim				Added "not running" as state
// 1.0.15				19.12.2025		William Veim				Minor bugfix ramping and added interlock return to normal as condition
// 1.0.16				15.01.2026		William Veim				Added logic for selecting usage of min/max values (scaling or limiting)
//	1.0.17				15.01.2026		William Veim				Added logic for updating symbol quality state
//	1.1.0					21.01.2026		William Veim				Added input for warning string - updates according to inp_warning state
//	1.1.1					03.03.2026		William Veim				Added delay before auto available switch (1s)
//	1.1.2					03.06.2026		William Veim				Removed "Inp_Ready" from Wrk_Enable (Needs to enable before ready state = TRUE)
//	1.1.3					18.06.2026		Ruben Byman				Added NOT Interlocked as criteria for available auto
//
//===============================================================================================================================
//
//		DESCRIPTION:
//		Common logic for VFD:
//		- SCADA interaction
//		- VFD Enabling
//		- VFD mode selection and command/reference source
//		- Runtime statistics
//
//==============================================================================================================================

(*************************************************************************
 *	INITIAL/SYSTEM VARIABELS
 *************************************************************************)
 
Wrk_CurrentTime := 					TruncTod(DT_TO_TOD(In:=GetTime()), _SEC);
Wrk_Date_Now := 						DT_TO_DATE(GetTime());
DayOfWeek:= 								GetDayOfWeek(In:=GetTime());
DtToDateStruct(In:=GetTime(), DateStruct=>Wrk_DT_Struct);
TOF_CPUStartup(In:=P_First_Run, PT:= T#5s);

(*************************************************************************
 *	INITIALISING VARIABELS
 *************************************************************************)

Ext_VFD.EXT_Alarm.Sts_SupressIfOff_Visible:=TRUE;

IF NOT Ext_VFD.INT_Data.Initialise THEN
	
	//Engeneering settings
	Ext_VFD.EXT_Engineering.Auto_Visible:=FALSE;
	Ext_VFD.EXT_Engineering.Auto_MinOutput:=0;
	Ext_VFD.EXT_Engineering.Auto_MaxOutput:=100;
	Ext_VFD.EXT_Engineering.RampTime:=60;
	Ext_VFD.EXT_Engineering.Timer_Output:=10;
	Ext_VFD.EXT_Engineering.Timer_RunTime:=10;
	Ext_VFD.EXT_Engineering.Timer_StartTime_Hour:=12;
	Ext_VFD.EXT_Engineering.Timer_StartTime_Minute:=00;
	Ext_VFD.EXT_Engineering.Timer_ActiveDays[0]:=TRUE;
	Ext_VFD.EXT_Engineering.Timer_ActiveDays[1]:=TRUE;
	Ext_VFD.EXT_Engineering.Timer_ActiveDays[2]:=TRUE;
	Ext_VFD.EXT_Engineering.Timer_ActiveDays[3]:=TRUE;
	
	//State config
	Ext_VFD.EXT_Engineering.StateCfg_1.Cfg_Quality:=4; //VFD error = Critical
	Ext_VFD.EXT_Engineering.StateCfg_1.Cfg_Alarm:=TRUE; //VFD error = Alarm
	Ext_VFD.EXT_Engineering.StateCfg_2.Cfg_Quality:=3; //VFD warning quality = Warning
	Ext_VFD.EXT_Engineering.StateCfg_2.Cfg_Alarm:=FALSE; //VFD warning quality = NOT Alarm
	Ext_VFD.EXT_Engineering.StateCfg_3.Cfg_Quality:=1; //Comm fault = Equipment failiure
	Ext_VFD.EXT_Engineering.StateCfg_3.Cfg_Alarm:=TRUE; //Comm fault = Alarm
	Ext_VFD.EXT_Engineering.StateCfg_4.Cfg_Quality:=0; //Emergency stop = Diagnostic
	Ext_VFD.EXT_Engineering.StateCfg_4.Cfg_Alarm:=TRUE; //Emergency stop = Alarm
	Ext_VFD.EXT_Engineering.StateCfg_5.Cfg_Quality:=0; //LOTO = Diagnostic
	Ext_VFD.EXT_Engineering.StateCfg_5.Cfg_Alarm:=TRUE; //LOTO = Alarm
	Ext_VFD.EXT_Engineering.StateCfg_6.Cfg_Quality:=0; //Interlock = Diagnostic
	Ext_VFD.EXT_Engineering.StateCfg_6.Cfg_Alarm:=TRUE; //Interlock = Alarm
	Ext_VFD.EXT_Engineering.StateCfg_7.Cfg_Quality:=0; //Start blocked = Diagnostic
	Ext_VFD.EXT_Engineering.StateCfg_7.Cfg_Alarm:=TRUE; //Start blocked = Alarm
	Ext_VFD.EXT_Engineering.StateCfg_8.Cfg_Quality:=0; //Not running = Diagnostic
	Ext_VFD.EXT_Engineering.StateCfg_8.Cfg_Alarm:=FALSE; //Not running =NOT Alarm
	
	//Statistic
	Ext_VFD.EXT_Statistics.OperatingHours_MotorService_Interval:=5000;
	
	//Alarm settings
	Ext_VFD.EXT_Alarm.Cfg_SupressDelayOff:=10;
	Ext_VFD.EXT_Alarm.Cfg_AlarmActiveDelay:=10;
	Ext_VFD.EXT_Alarm.Cfg_AlarmReturnDelay:=10;
	
	//Init complete
	Ext_VFD.INT_Data.Initialise:=TRUE;
	
END_IF;

//FORCING VARIABLES
Ext_VFD.EXT_Engineering.StateCfg_1.Cfg_Action:=99;//VFD error loced to "OFF"
Ext_VFD.EXT_Engineering.StateCfg_3.Cfg_Action:=100;//Comm fault loced to None, button invisible
Ext_VFD.EXT_Engineering.StateCfg_4.Cfg_Action:=99;//Emergency stop loced to "OFF"
Ext_VFD.EXT_Engineering.StateCfg_5.Cfg_Action:=99;//LOTO loced to "OFF"
Ext_VFD.EXT_Engineering.StateCfg_6.Cfg_Action:=99;//Interlock loced to "OFF"
Ext_VFD.EXT_Engineering.StateCfg_7.Cfg_Action:=99;//Start blocked loced to "OFF"

(*************************************************************************
 *	GENERATING INTERNAL VARIABLES
 *************************************************************************)

Wrk_StartBlocked := 	  (Wrk_StartBlocked AND NOT (Ext_VFD.EXT_Engineering.Reset_Error OR Ext_VFD.EXT_Operator.Reset_Error)) //Hold and reset 
								OR (Inp_LocalStop) //Local stop
								OR (Inp_LOTO AND Cfg_LOTO_InUse) //LOTO inp and in use 
								OR (Inp_STO AND Cfg_STO_InUse); //STO inp and in use

Wrk_Enable:=	     Inp_Online
					AND Inp_VoltageEnabled
					AND NOT Inp_Error 
					AND NOT (Inp_STO AND Cfg_STO_InUse)
					AND NOT (Inp_LOTO AND Cfg_LOTO_InUse);				

TON_AutoAvail_SwichDelay(In:=NOT Wrk_Enable, PT:=T#1s);

IF Wrk_Enable AND Inp_Ready AND Ext_VFD.EXT_Operator.Mode = 2 AND NOT Inp_Interlock THEN
	Wrk_AvailableAuto := TRUE;
ELSIF NOT TOF_CPUStartup.Q AND (TON_AutoAvail_SwichDelay.Q OR Ext_VFD.EXT_Operator.Mode <> 2) THEN
	Wrk_AvailableAuto := FALSE;
END_IF;

(*************************************************************************
 *	MODE CONTROL
 *************************************************************************)

IF NOT Ext_VFD.EXT_Engineering.ReverseRunning_Start THEN
	CASE Ext_VFD.EXT_Operator.Mode OF
			
		    0://Av
			
					//Output control				
					Wrk_CmdSpeedRef := 0.0;
					Wrk_TmpRunFwd := FALSE;
					
			1://Man	
			
					//Output control
					Wrk_TmpRunFwd := Ext_VFD.EXT_Operator.Manual_Gain > 0.0;
					Wrk_CmdSpeedRef := Ext_VFD.EXT_Operator.Manual_Gain;
					
			2://Auto
			
					IF NOT TOF_CPUStartup.Q THEN //Controller startup and update controller data
						
						//Command control
						Wrk_TmpRunFwd:= Inp_AutoRunFwd AND Inp_AutoSpeedRef > 0.2;
				
						//Output control
						//SCALING AUTO GAIN
						IF NOT Ext_VFD.EXT_Engineering.Auto_MinMax_Type AND Inp_AutoRunFwd THEN
							
						Wrk_CmdSpeedRef := ScaleTrans(SclIn:=Inp_AutoSpeedRef, 
																				X0:=0.0, 
																				Y0:=Ext_VFD.EXT_Engineering.Auto_MinOutput, 
																				X1:=100.0, 
																				Y1:=Ext_VFD.EXT_Engineering.Auto_MaxOutput);
						
						//USE AUTO GAIN DIRECT WHIT LIMITATION
						ELSIF Ext_VFD.EXT_Engineering.Auto_MinMax_Type AND Inp_AutoRunFwd THEN
							
						Wrk_CmdSpeedRef := Inp_AutoSpeedRef;
						Wrk_CmdSpeedRef:=LIMIT(MN:=Ext_VFD.EXT_Engineering.Auto_MinOutput, In:=Wrk_CmdSpeedRef, MX:=Ext_VFD.EXT_Engineering.Auto_MaxOutput);
						
						ELSE
							
							Wrk_CmdSpeedRef:=0.0;
							
						END_IF;
					END_IF;
					
			3://Timer
					
					CASE DayOfWeek OF
			
								_MON:
								Wrk_TimerMode_DayActive := Ext_VFD.EXT_Engineering.Timer_ActiveDays[0];//Active if pos 0 in array configured (TRUE)
								
								_TUE:
								Wrk_TimerMode_DayActive := Ext_VFD.EXT_Engineering.Timer_ActiveDays[1]; //Active if pos 1 in array configured (TRUE)
								
								_WED:
								Wrk_TimerMode_DayActive := Ext_VFD.EXT_Engineering.Timer_ActiveDays[2]; //Active if pos 2 in array configured (TRUE)
								
								_THU:
								Wrk_TimerMode_DayActive := Ext_VFD.EXT_Engineering.Timer_ActiveDays[3]; //Active if pos 3 in array configured (TRUE)
								
								_FRI:
								Wrk_TimerMode_DayActive := Ext_VFD.EXT_Engineering.Timer_ActiveDays[4]; //Active if pos 4 in array configured (TRUE)
								
								_SAT:
								Wrk_TimerMode_DayActive := Ext_VFD.EXT_Engineering.Timer_ActiveDays[5]; //Active if pos 5 in array configured (TRUE)
								
								_SUN:
								Wrk_TimerMode_DayActive := Ext_VFD.EXT_Engineering.Timer_ActiveDays[6]; //Active if pos 6 in array configured (TRUE)
								
					END_CASE;

					//Start control (based on time of day)
					RE_TimerStart(Clk:=Wrk_CurrentTime = HE_INT2TOD(Hour:=Ext_VFD.EXT_Engineering.Timer_StartTime_Hour, Minute:=Ext_VFD.EXT_Engineering.Timer_StartTime_Minute) AND Wrk_TimerMode_DayActive);
					TON_Timer(PT:=SecToTime(Ext_VFD.EXT_Engineering.Timer_RunTime));
					
					IF RE_TimerStart.Q THEN
						Wrk_TimerStarted:=TRUE;
					END_IF;
						
					IF Wrk_TimerStarted THEN
						TON_Timer.In:=TRUE;
						IF TON_Timer.Q THEN
							Wrk_TimerStarted:=FALSE;
							TON_Timer.In:=FALSE;
						END_IF;
					END_IF;
						
					IF Wrk_TimerStarted THEN	
						Wrk_TmpRunFwd := TRUE;
						Wrk_CmdSpeedRef := Ext_VFD.EXT_Engineering.Timer_Output;
					ELSE
						Wrk_TmpRunFwd := FALSE;
						Wrk_CmdSpeedRef := 0.0;
					END_IF;

	END_CASE;

//Start reverse running
ELSE
	Wrk_TmpRunFwd:=FALSE; //Ensure stop

END_IF;

//Start reverse running when VFD stopped
IF Ext_VFD.EXT_Engineering.ReverseRunning_Start AND NOT Inp_RunningFwd THEN
Wrk_CmdSpeedRef := Ext_VFD.EXT_Engineering.ReverseRunning_Output;
Wrk_TmpRunRev := TRUE;
//Stop when disabled
ELSIF NOT Ext_VFD.EXT_Engineering.ReverseRunning_Start THEN
Wrk_TmpRunRev := FALSE;
END_IF;

(*************************************************************************
 *	STATISTIC DATA
 *************************************************************************)

//Executing statistic FB (accumulation timer)
FB_Statistics(Inp_Feedback:=Inp_RunningFwd OR Inp_RunningRev, 
					Inp_Reset_Total:=Ext_VFD.EXT_Statistics.Reset_MotorTotal, 
					Inp_Reset_Service:=Ext_VFD.EXT_Statistics.Reset_MotorService);

//Retriving data for statistic FB
Ext_VFD.EXT_Statistics.ResetDate_MotorTotal					:= FB_Statistics.Out_ResetDate_Total;
Ext_VFD.EXT_Statistics.ResetDate_MotorService 			:=	FB_Statistics.Out_ResetDate_Service;
Ext_VFD.EXT_Statistics.OperatingHours_MotorTotal		:= LINT_TO_UDINT(TimeToSec(In:= FB_Statistics.Out_RunTime_Total) / 3600);
Ext_VFD.EXT_Statistics.OperatingHours_MotorService	:= LINT_TO_UDINT(TimeToSec(In:= FB_Statistics.Out_RunTime_Service) / 3600);
Ext_VFD.EXT_Statistics.NumberOfStarts 							:= ULINT_TO_UDINT(FB_Statistics.Out_NumOfStarts);

//Converting data to structure
Ext_VFD.EXT_Statistics.Ontime_VFD:=ULINT_TO_UDINT(Inp_VFD_TotalOnTime/24);
Ext_VFD.EXT_Statistics.Runtime_VFD:=ULINT_TO_UDINT(Inp_VFD_TotalRunTime/24);

//Reset time stamp when VFD running hours below 3h (asuming VFD have beed replaced)
RE_ResetDateVFD(Clk:= Ext_VFD.EXT_Statistics.Runtime_VFD < 3  AND NOT Inp_ComFault AND NOT TOF_CPUStartup.Q);

IF RE_ResetDateVFD.Q THEN
	Ext_VFD.EXT_Statistics.ResetDate_VFD := DateToString(Wrk_Date_Now);
END_IF;

//ENERGY CONSUMPTION
//---------------------------

IF Wrk_DaySample <> Wrk_DT_Struct.Day THEN
	Wrk_DaySample := Wrk_DT_Struct.Day;
	Ext_VFD.EXT_Statistics.EnergyConsumption_Yesterday:=Inp_Energy - Wrk_Energi_Capture;
	Wrk_Energi_Capture := Inp_Energy;
	
ELSIF Wrk_Energi_Capture > Inp_Energy AND NOT TOF_CPUStartup.Q THEN
	Wrk_Energi_Capture := Inp_Energy;
END_IF;

Ext_VFD.EXT_Statistics.EnergyConsumption_Today:= Inp_Energy - Wrk_Energi_Capture;

Ext_VFD.EXT_Statistics.Power := 		Inp_Power;
Ext_VFD.EXT_Statistics.Current := 	Inp_Current;

(*************************************************************************
 *	VFD STATE AND MODE
 *************************************************************************)

//Updating active error
IF Inp_ComFault THEN
	Ext_VFD.EXT_Operator.Active_Error:= 'Communication fault';
ELSIF Inp_Error THEN
	Ext_VFD.EXT_Operator.Active_Error:= Inp_Active_Error;
ELSIF Inp_Warning THEN
	Ext_VFD.EXT_Operator.Active_Error:= Inp_Active_Warning;
ELSE
	Ext_VFD.EXT_Operator.Active_Error:= 'No fault';
END_IF;

//Updating last error
IF Ext_VFD.EXT_Operator.Active_Error <> 'No fault' THEN
	Ext_VFD.EXT_Engineering.Last_Error:= Ext_VFD.EXT_Operator.Active_Error;
END_IF;

//Updating actual state
IF Inp_ComFault THEN
	Ext_VFD.EXT_Operator.Actual_State:= 	'Unknown state';
ELSIF Inp_STO THEN
	Ext_VFD.EXT_Operator.Actual_State:= 	Inp_Actual_State;
ELSIF Inp_LOTO THEN
	Ext_VFD.EXT_Operator.Actual_State:= 	'LOTO (Servicebreaker) active';
ELSIF Wrk_StartBlocked THEN
	Ext_VFD.EXT_Operator.Actual_State:= 	'Start blocked';
ELSIF Inp_Interlock THEN
	Ext_VFD.EXT_Operator.Actual_State:= 	'Interlocked';
ELSE
	Ext_VFD.EXT_Operator.Actual_State:=		Inp_Actual_State;
END_IF;

(*************************************************************************
 *	STATE CONTROL
 *************************************************************************)

//Resetter variabler før løkke
Ext_VFD.EXT_General.Sts_Quality:= 6; //Good
Wrk_ActionState:=	0;

//VFD fault
HE_StateControl(EXT_StateData:=Ext_VFD.EXT_Engineering.StateCfg_1, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Inp_Error, 
							Inp_Desc:='VFD error', 
							Sts_Quality:=Ext_VFD.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[0].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[0].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[0].Alm_Priority);

//VFD warning
HE_StateControl(EXT_StateData:=Ext_VFD.EXT_Engineering.StateCfg_2, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Inp_Warning, 
							Inp_Desc:='VFD warning', 
							Sts_Quality:=Ext_VFD.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[1].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[1].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[1].Alm_Priority);

//Communication fault
HE_StateControl(EXT_StateData:=Ext_VFD.EXT_Engineering.StateCfg_3, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Inp_ComFault, 
							Inp_Desc:='Communication fault', 
							Sts_Quality:=Ext_VFD.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[2].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[2].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[2].Alm_Priority);

//Emergency stop
HE_StateControl(EXT_StateData:=Ext_VFD.EXT_Engineering.StateCfg_4, 
							Inp_Visibility:=Cfg_STO_InUse, 
							Inp_State:=Inp_STO, 
							Inp_Desc:='Emergency stop', 
							Sts_Quality:=Ext_VFD.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[3].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[3].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[3].Alm_Priority);

//LOTO/Service breaker
HE_StateControl(EXT_StateData:=Ext_VFD.EXT_Engineering.StateCfg_5, 
							Inp_Visibility:=Cfg_LOTO_InUse, 
							Inp_State:=Inp_LOTO, 
							Inp_Desc:='LOTO', 
							Sts_Quality:=Ext_VFD.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[4].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[4].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[4].Alm_Priority);

//Interlock
HE_StateControl(EXT_StateData:=Ext_VFD.EXT_Engineering.StateCfg_6, 
							Inp_Visibility:=Cfg_Interlock_InUse, 
							Inp_State:=Inp_Interlock, 
							Inp_Desc:='Interlock', 
							Sts_Quality:=Ext_VFD.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[5].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[5].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[5].Alm_Priority);

//Start blocked
HE_StateControl(EXT_StateData:=Ext_VFD.EXT_Engineering.StateCfg_7, 
							Inp_Visibility:=TRUE, 
							Inp_State:=Wrk_StartBlocked, 
							Inp_Desc:='Start blocked', 
							Sts_Quality:=Ext_VFD.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[6].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[6].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[6].Alm_Priority);

//Not running
HE_StateControl(EXT_StateData:=Ext_VFD.EXT_Engineering.StateCfg_8, 
							Inp_Visibility:=Ext_VFD.EXT_Engineering.StateCfg_NotRunning_Visible, 
							Inp_State:=NOT Inp_RunningFwd AND NOT Inp_RunningRev, 
							Inp_Desc:='Not Running', 
							Sts_Quality:=Ext_VFD.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[7].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[7].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[7].Alm_Priority);

//Motor service required
HE_StateControl(EXT_StateData:=Ext_VFD.EXT_Engineering.StateCfg_9, 
							Inp_Visibility:=Ext_VFD.EXT_Engineering.StateCfg_ServiceHours_Visible, 
							Inp_State:=Ext_VFD.EXT_Statistics.OperatingHours_MotorService > Ext_VFD.EXT_Statistics.OperatingHours_MotorService_Interval, 
							Inp_Desc:='Motor service required', 
							Sts_Quality:=Ext_VFD.EXT_General.Sts_Quality, 
							Sts_ActionState:=Wrk_ActionState, 
							Sts_AlarmSuffix=>Wrk_AlarmData[8].Alm_Suffix, 
							Sts_AlarmState=>Wrk_AlarmData[8].Alm_State,
							Sts_AlarmPriority=>Wrk_AlarmData[8].Alm_Priority);

CASE Wrk_ActionState OF
	
	0://Continue operation
	Wrk_SpeedRefOutput:= Wrk_CmdSpeedRef;
	
	1://Freeze output
	Wrk_SpeedRefOutput:=Wrk_SpeedRefOutput;
	
	2://Predefined output
	Wrk_SpeedRefOutput:=Ext_VFD.EXT_Engineering.StateCfg_PreDefinedOutput;
	
	3://OFF
	Wrk_SpeedRefOutput:=0;
	
END_CASE;

(*************************************************************************
 *	OUTPUT REFERENCE CONTROL (Ramping and deadband)
 *************************************************************************)

//Rising edge trigger
FE_InterlockNormalState(Clk:=	Inp_Interlock);
RE_AutoEng(Clk:=						Ext_VFD.EXT_Operator.Mode=2 AND Inp_AutoRunFwd AND Inp_AutoSpeedRef>0);
RE_MinMax_Adjusted(Clk:=			Ext_VFD.EXT_Operator.Mode=2 AND (Wrk_MinOutputSample <> Ext_VFD.EXT_Engineering.Auto_MinOutput OR Wrk_MaxOutputSample <> Ext_VFD.EXT_Engineering.Auto_MaxOutput));
TON_RampEngage(In:=				Wrk_AutoEng OR Wrk_InterlockNormalState OR Wrk_MinOrMax_Adjusted, PT:=SecToTime(Ext_VFD.EXT_Engineering.RampTime));

Wrk_MinOutputSample:=Ext_VFD.EXT_Engineering.Auto_MinOutput;
Wrk_MaxOutputSample:=Ext_VFD.EXT_Engineering.Auto_MaxOutput;

IF RE_AutoEng.Q AND NOT TOF_CPUStartup.Q THEN
	Wrk_AutoEng:=TRUE;
END_IF;

IF RE_MinMax_Adjusted.Q  AND NOT TOF_CPUStartup.Q THEN
	Wrk_MinOrMax_Adjusted:=TRUE;
END_IF;

IF FE_InterlockNormalState.Q AND NOT TOF_CPUStartup.Q THEN
	Wrk_InterlockNormalState:=TRUE;
END_IF;

IF TON_RampEngage.Q THEN
	Wrk_AutoEng:=FALSE;
	Wrk_InterlockNormalState:=FALSE;
	Wrk_MinOrMax_Adjusted:=FALSE;
END_IF;

//When activating AUTO mode or interlock normalizes in AUTO mode, output is ramped from previous output to AUTO output
FB_RampGain(ENS:=TRUE, 
						Inp_RampStart:=Wrk_AutoEng OR Wrk_MinOrMax_Adjusted OR Wrk_InterlockNormalState, 
						Inp_Value:=Wrk_SpeedRefOutput, 
						Cfg_StrokeTime:=SecToTime(Ext_VFD.EXT_Engineering.RampTime), 
						Cfg_Output_X0:=Ext_VFD.EXT_Engineering.Auto_MinOutput, 
						Cfg_Output_X1:=Ext_VFD.EXT_Engineering.Auto_MaxOutput, 
						Cfg_Resolution:=FALSE, 
						Out_Output=>Wrk_SpeedRamped);

(*************************************************************************
 *	OUTPUT COMMAND CONTROL
 *************************************************************************)

Wrk_CmdRunFwd:=Wrk_SpeedRamped > 0.2 AND Wrk_TmpRunFwd AND NOT Wrk_StartBlocked AND NOT Inp_Interlock AND Wrk_Enable;
Wrk_CmdRunRev:=Wrk_SpeedRamped > 0.2 AND Wrk_TmpRunRev AND NOT Wrk_TmpRunFwd AND NOT Wrk_StartBlocked AND NOT Inp_Interlock AND Wrk_Enable;

(*************************************************************************
 *	ALARM CONTROL
 *************************************************************************)

//Supress if off mode
IF Ext_VFD.EXT_Alarm.Sts_SupressIfOff_Visible AND Ext_VFD.EXT_Alarm.Cfg_SupressIfOff AND Ext_VFD.EXT_Operator.Mode = 0 THEN
	FB_AlarmGeneral.Inp_AlarmSupress:=TRUE;
	FB_AlarmGeneral.Inp_AlmSuppressDesc:= 'Off mode';
//Supress from FB input
ELSIF Inp_AlmSuppress THEN
	FB_AlarmGeneral.Inp_AlarmSupress:=TRUE;
	FB_AlarmGeneral.Inp_AlmSuppressDesc:= Inp_AlmSuppressDesc;
ELSE
	FB_AlarmGeneral.Inp_AlarmSupress:=FALSE;
END_IF;

(*************************************************************************
 *	EXCECUTING ALARM BLOCK
 *************************************************************************)
 
 FB_AlarmGeneral(ENS:=TRUE, 
								 Ext_Alarm:=Ext_VFD.EXT_Alarm, 
								 Int_Alarm:=Int_Alarm, 
								 Inp_AlarmData:=Wrk_AlarmData,
								 Inp_LocationData:=Ext_VFD.EXT_General.LocationIndex,
								 Inp_AlarmSupress:=Inp_AlmSuppress, 
								 Inp_AlmSuppressDesc:=Inp_AlmSuppressDesc, 
								 Inp_Connected_Cabinet:=Ext_VFD.EXT_Engineering.Supply_Switchboard, 
								 Inp_Connected_Controller:=Cfg_ControllerTAG, 
								 Inp_Process_TAG:=Cfg_ProcessTAG, 
								 Inp_Process_Desc:=Ext_VFD.EXT_General.Process_Desc,
								 Out_AlarmToken=>Wrk_AlarmToken, 
								 Out_AlarmTriggered=>Wrk_AlarmTriggered,
								 Inp_Process_Value:= CONCAT(RealToFormatString(Ext_VFD.EXT_Operator.Feedback_Gain,FALSE,FALSE,2,2), '%'));

(*************************************************************************
 *	OUTPUT DATA
 *************************************************************************)
 
 // Pulse Auto Reset
TOF_ResetVFDFault(In:=Ext_VFD.EXT_Engineering.Reset_Error OR Ext_VFD.EXT_Operator.Reset_Error, PT:=TIME#500ms);

//STRUCTURE DATA
//-----------------------------------------

Ext_VFD.EXT_General.Process_TAG:=							Cfg_ProcessTAG;
Ext_VFD.EXT_General.Controlled_FromController:=	Cfg_ControllerTAG;
Ext_VFD.EXT_Operator.CalculatedFlow_Visible:=		FALSE; //Will be set true in flow FB (if in use)
Ext_VFD.EXT_Operator.Feedback_Gain := 					Inp_ActSpeed;
Ext_VFD.EXT_Operator.Actual_Gain := 						Wrk_SpeedRefOutput;
Ext_VFD.EXT_General.Remote := 								Inp_Remote;
Ext_VFD.EXT_General.Running := 								Inp_RunningFwd OR Inp_RunningRev;
Ext_VFD.INT_Data.CommunicationFault := 					Inp_ComFault;
Ext_VFD.INT_Data.Running:= 										Inp_RunningFwd OR Inp_RunningRev;
Ext_VFD.INT_Data.Fault := 											Inp_Error;
Ext_VFD.INT_Data.Warning := 										Inp_Warning;
Ext_VFD.INT_Data.Emergency_Stop := 						Inp_STO;
Ext_VFD.INT_Data.Fault:= 											Inp_Error OR (Inp_ComFault AND NOT TOF_CPUStartup.Q);
Ext_VFD.INT_Data.AutoAvailable:= 								Wrk_AvailableAuto;

// Reset SCADA Commands
Ext_VFD.EXT_Engineering.Reset_Error := 					FALSE;
Ext_VFD.EXT_Operator.Reset_Error := 							FALSE;
Ext_VFD.EXT_Statistics.Reset_MotorService := 			FALSE;
Ext_VFD.EXT_Statistics.Reset_MotorTotal := 				FALSE;

 //BLOCK OUTPUT
 //------------------

Out_Enable:=  				Wrk_Enable;// Switch on / Contactor command
Out_RunFwd := 			Wrk_CmdRunFwd; // Run Forward
Out_RunRev:=				Wrk_CmdRunRev; // Run Reverse
Out_SpeedRef := 		Wrk_SpeedRamped; //Speed reference
Out_FaultReset := 		TOF_ResetVFDFault.Q; // Reset fault
Sts_AvailableAuto := 	Wrk_AvailableAuto; //Status available for auto ref
Sts_Interlock := 			Inp_Interlock; //Status interlocked
Sts_AlarmTriggered:=	Wrk_AlarmTriggered;
Sts_AlarmToken:=		Wrk_AlarmToken;
